#!/bin/zsh
# native_disp2_plant.sh - planted breaks for tests/native_disp2_test.cpp (build 0.0.631, multi-monitor stage M4d: `disp2 timing|connect|off|status`, the OTG1 -> DIG2 test pattern).
# Discipline (as native_dmubcmd_plant.sh): copy the sources the test reads into a scratch tree, apply ONE break to the REAL code (the pure header, the flow, the kernel glue, the dispatch, the admission, the CLI, the plist),
# build the real test against the copy and demand it FAILS (a compile error, a failing check, a crash or a hang all count). A plant whose text is not found exactly once is itself reported as an escape.
# The CONTROL (no break) must pass. The Linux headers and the EDID capture are read from the main checkout (the test's fallback root), never modified.
#   run from anywhere:  src/navi48-bringup/tests/native_disp2_plant.sh [first-plant-id last-plant-id]
ROOT="$(cd "$(dirname "$0")/../../.." && pwd)"
exec python3 -u - "$ROOT" "${1:-0}" "${2:-9999}" <<'PY'
import os, shutil, subprocess, sys, tempfile, time

ROOT, FIRST, LAST = sys.argv[1], int(sys.argv[2]), int(sys.argv[3])
K = 'src/navi48-bringup'
H, F, G, BRG, PURE, UCL, CLI, PLIST, S1C, HPP = (f'{K}/src/dcn/navi48_disp2.h', f'{K}/src/dcn/navi48_disp2_flow.h', f'{K}/src/dcn/navi48_dcn.cpp', f'{K}/src/Navi48Bringup.cpp', f'{K}/src/amd/native_disp_pure.h',
    f'{K}/src/Navi48UserClient.cpp', 'tools/pc/navi48test.c', f'{K}/Info.plist', f'{K}/src/amd/native_s1c.h', f'{K}/src/dcn/navi48_dcn.hpp')
S1CPP = f'{K}/src/amd/native_s1c.cpp'      # 0.0.635: the helper that allocates / frees the monitor B's two buffers under gCliLock
COPY_DIRS = [f'{K}/src/amd', f'{K}/src/dcn', 'src/dcn41']
COPY_FILES = [BRG, UCL, CLI, PLIST, S1C, f'{K}/src/Navi48MetalNub.cpp', f'{K}/src/Navi48MetalOps.h', f'{K}/src/Navi48DisplayOps.h', f'{K}/src/Navi48NativeABI.h', f'{K}/src/amd/native_m6_pure.h', f'{K}/src/apple/display_pipe_guard.h', f'{K}/tests/native_disp2_test.cpp', f'{K}/tests/native_disp2_plant.sh']

scr = tempfile.mkdtemp(prefix='ndisp2-plant.')
def fresh():
    shutil.rmtree(scr, ignore_errors=True)
    for d in COPY_DIRS:
        shutil.copytree(os.path.join(ROOT, d), os.path.join(scr, d), ignore=shutil.ignore_patterns('*.o', 'build*'))
    for f in COPY_FILES:
        d = os.path.join(scr, f); os.makedirs(os.path.dirname(d), exist_ok=True); shutil.copy(os.path.join(ROOT, f), d)
def build_run():
    cmd = ['clang++', '-std=c++17', '-Wall', '-Wextra', '-Werror', '-O1', '-fsanitize=address,undefined', '-fno-sanitize-recover=all', '-I', f'{K}/src', '-I', f'{K}/src/dcn', '-I', f'{K}/src/amd', '-I', 'src/dcn41',
           f'{K}/tests/native_disp2_test.cpp', '-x', 'c++', 'src/dcn41/dcn41_allow.c', '-o', os.path.join(scr, 't')]
    r = subprocess.run(cmd, cwd=scr, capture_output=True, text=True)
    if r.returncode != 0:
        first = next((l for l in (r.stderr + r.stdout).splitlines() if 'error' in l), '')
        return 2, 'CAUGHT at compile time: ' + first[:140]
    try:
        r = subprocess.run([os.path.join(scr, 't'), '.'], cwd=scr, capture_output=True, text=True, timeout=120)
    except subprocess.TimeoutExpired:
        return 1, 'CAUGHT by a hang'
    if os.environ.get('N48_PLANT_SHOW'): print('\n'.join((r.stdout + r.stderr).splitlines()[-40:]))
    if r.returncode == 0: return 0, 'the suite passed: ' + r.stdout.strip().splitlines()[-1]
    if r.returncode < 0: return 1, 'CAUGHT by a crash (signal %d)' % -r.returncode
    fails = [l for l in r.stdout.splitlines() if l.startswith('FAIL')]
    return 1, 'CAUGHT by %d check(s); first: %s' % (len(fails), (fails[0] if fails else r.stdout.strip().splitlines()[-1])[:120])

total = escaped = 0
def control():
    global total, escaped
    fresh(); total += 1
    rc, msg = build_run()
    if rc != 0: print('CONTROL: *** FAILED UNMODIFIED (%s) ***' % msg); escaped += 1
    else: print('CONTROL: ' + msg)
def plant(pid, path, desc, old, new):
    global total, escaped
    if pid < FIRST or pid > LAST: return
    fresh(); total += 1
    f = os.path.join(scr, path); s = open(f).read()
    n = s.count(old)
    if n != 1:
        print('PLANT %d: %s: PLANT TEXT NOT FOUND EXACTLY ONCE (%d)' % (pid, desc, n)); escaped += 1; return
    if os.environ.get('N48_PLANT_DRY'): print('PLANT %d: text found exactly once (dry run)' % pid); return
    open(f, 'w').write(s.replace(old, new))
    t0 = time.time(); rc, msg = build_run(); dt = time.time() - t0
    if rc == 0: print('PLANT %d: %s: *** ESCAPED (%s) *** [%.1fs]' % (pid, desc, msg, dt)); escaped += 1
    else: print('PLANT %d: %s: %s [%.1fs]' % (pid, desc, msg, dt))

def plant2(pid, path, desc, pairs):
    """0.0.655: a break that needs TWO exact-once edits in one file (e.g. the builder table AND the guard's pin table)."""
    global total, escaped
    if pid < FIRST or pid > LAST: return
    fresh(); total += 1
    f = os.path.join(scr, path); s = open(f).read()
    for old, new in pairs:
        if s.count(old) != 1:
            print('PLANT %d: %s: PLANT TEXT NOT FOUND EXACTLY ONCE (%d)' % (pid, desc, s.count(old))); escaped += 1; return
    if os.environ.get('N48_PLANT_DRY'): print('PLANT %d: text found exactly once (dry run)' % pid); return
    for old, new in pairs: s = s.replace(old, new)
    open(f, 'w').write(s)
    t0 = time.time(); rc, msg = build_run(); dt = time.time() - t0
    if rc == 0: print('PLANT %d: %s: *** ESCAPED (%s) *** [%.1fs]' % (pid, desc, msg, dt)); escaped += 1
    else: print('PLANT %d: %s: %s [%.1fs]' % (pid, desc, msg, dt))

